        for j in range(i):
            if arr[j] < arr[i]:
                inc_sum[i] = max(inc_sum[i], inc_sum[j] + arr[i])

    # Fill dec_sum: maximum sum of decreasing subsequence starting at i
    for i in range(n - 1, -1, -1):
        dec_sum[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec_sum[i] = max(dec_sum[i], dec_sum[j] + arr[i])

    # Find maximum bitonic sum
    max_sum = 0
