def babylonian_sqrt(n, tolerance=1e-10):
    if n < 0:
        raise ValueError("Cannot compute square root of negative number")
    if n == 0 or n == 1:
        return n

    # Initial guess
    x = n / 2.0

    while True:
        # Improved guess using the Babylonian formula
        root = 0.5 * (x + n / x)

        # Check for convergence
        if abs(root - x) < tolerance:
            return root

        x = root

