    while left <= right:
        # If the array is already sorted
        if arr[left] <= arr[right]:
            return left

        mid = (left + right) // 2

        # Check if mid is the pivot (smallest element)
        # Pivot is the only element where previous element is greater than current
        if mid > 0 and arr[mid] < arr[mid - 1]:
            return mid

        # If left half is sorted, pivot must be in right half
        if arr[left] <= arr[mid]:
            left = mid + 1
        else:
